head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf31010";
scwin.panel_3 = null;
scwin.grd_Grid = null;
scwin.panel_page = null;
scwin.gNowDutyYn = '';
scwin.gNowDutyStat = '';
scwin.dts_OneGrid = null;
scwin.dts_DutyStatus = null;
scwin.dts_CloseProcs = null;
scwin.dts_Grid = null;
scwin.dts_CodeEmpNo = null;
scwin.dts_CodeChrgEmpNo = null;
scwin.gLdMktTp = undefined;
scwin.gDutyID = undefined;
scwin.fn_OneSearch = null;
scwin.fn_SetCode = null;
scwin.fn_HistorySearch = null;
scwin.fn_CloseProcess = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        PanelToGroupBox(scwin.panel_3);
        ipt_txb_EMP_NM.setValue($c.session.getUserInfo("empNm"));
        scwin.fn_SetCode();
        scwin.dts_CloseProcs.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=PERSONONDUTY_HISTORY_IN";
        scwin.dts_CloseProcs.reset();
        scwin.fn_OneSearch();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf31010.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.gLdMktTp =$c.session.getUserInfo("market"); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf31010' }); }

try { scwin.gDutyID =js_duty; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf31010' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.panel_3 = $c.util.getComponent('panel_3');
        scwin.grd_Grid = $c.util.getComponent('grd_Grid');
        scwin.panel_page = $c.util.getComponent('panel_page');
        scwin.dts_OneGrid = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_OneGrid')) : $c.util.getComponent('dts_OneGrid');
        scwin.dts_DutyStatus = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_DutyStatus')) : $c.util.getComponent('dts_DutyStatus');
        scwin.dts_CloseProcs = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_CloseProcs')) : $c.util.getComponent('dts_CloseProcs');
        scwin.dts_Grid = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_Grid')) : $c.util.getComponent('dts_Grid');
        scwin.dts_CodeEmpNo = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_CodeEmpNo')) : $c.util.getComponent('dts_CodeEmpNo');
        scwin.dts_CodeChrgEmpNo = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_CodeChrgEmpNo')) : $c.util.getComponent('dts_CodeChrgEmpNo');
        scwin.fn_OneSearch = scwin.tx_script_dts_OneGrid;
        scwin.fn_SetCode = scwin.tx_script_dts_CodeChrgEmpNo;
        scwin.fn_HistorySearch = scwin.tx_script_dts_Grid;
        scwin.fn_CloseProcess = scwin.sbm_trs_CloseProcs;
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf31010.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
