};

/**
 * @method
 * @name trs_CloseProcs_onsuccess
 * @description 알림을 띄운다 외
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_CloseProcs_onsuccess = async function () {
    try {
        await $c.win.alert($c.data.getMessage("MSG-0001", ""));
        scwin.fn_OneSearch();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldstf31010.trs_CloseProcs_onsuccess" });
    }
};

/**
 * @method
 * @name trs_CloseProcs_onfail
 * @description 알림을 띄운다
