/**
 * @method
 * @name MxTab_1_onselchanged
 * @description MxTab_1 onselchanged 이벤트
 * @param {*} nIndex nIndex
 * @returns {void}
 * @hidden N
 */
scwin.MxTab_1_onselchanged = function (nIndex) {
    try {
        if (MxTab_1.selectedIndex === 1) {
            scwin.fn_OneSearch();
        } else {
            if (MxTab_1.selectedIndex === 2) {
                scwin.fn_HistorySearch();
            }
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf31010.MxTab_1_onselchanged' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_script_dts_CodeChrgEmpNo
 * @description script dts Code Chrg Emp No 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_script_dts_CodeChrgEmpNo = async function () {
    $c.util.getComponent("dma_scriptDts_CodeChrgEmpNoReq").set("ROLL_CD", "09");
    $c.util.getComponent("dma_scriptDts_CodeChrgEmpNoReq").set("For", "R/CodeAction.do");
    // as-is 가 URL 에 싣던 값을 정적으로 못 읽었다 — 빈 파라미터로 보내지 않는다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "보낼 입력값을 아직 읽지 못합니다(전환 미완) — DEP_CD, TEAM_ID"
    throw { bizMessage: "보낼 입력값을 아직 읽지 못합니다(전환 미완) — DEP_CD, TEAM_ID", unresolved: "query_param:DEP_CD,TEAM_ID" };
    const sbmOptions = {
        id: "tx_script_dts_CodeChrgEmpNo",
        method: "post",
        action: "/CodeAction.do",
        ref: "dma_scriptDts_CodeChrgEmpNoReq",
        target: "dts_CodeChrgEmpNo=body.content",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['dts_CodeChrgEmpNo_onloaderror'] === 'function') ? scwin['dts_CodeChrgEmpNo_onloaderror'] : (typeof scwin['dts_CodeChrgEmpNo_onfail'] === 'function') ? scwin['dts_CodeChrgEmpNo_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['dts_CodeChrgEmpNo_onloadcompleted'] === 'function') ? scwin['dts_CodeChrgEmpNo_onloadcompleted'] : ((typeof scwin['dts_CodeChrgEmpNo_onsuccess'] === 'function') ? scwin['dts_CodeChrgEmpNo_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('dts_CodeChrgEmpNo'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf31010.tx_script_dts_CodeChrgEmpNo" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

