///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setTime
 * @description set Time 처리
 * @returns {void}
 * @hidden N
 */
scwin.setTime = function () {
    const vCurDate = $c.date.formatDate("yyyy-mm-dd hh:mm:ss");
    ipt_txbNow.setValue("현재시각 : " + vCurDate);
    scwin.runClock();
};

/**
 * @method
 * @name runClock
 * @description run Clock 처리
 * @returns {void}
 * @hidden N
 */
scwin.runClock = function () {
    setTimeout(function(){ scwin.setTime() }, 1000);
};

/**
 * @method
 * @name checkStatus
 * @description check Status 처리
 * @returns {void}
 * @hidden N
 */
scwin.checkStatus = function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.fil.fn_checkDutyTimeStatus
    $c.fil.fn_checkDutyTimeStatus($c.session.getUserInfo("empNo"), '', scwin.dts_DutyStatus);
};

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)
